using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var sc = EditorSceneManager.GetActiveScene();
            if (sc.isDirty || !sc.path.EndsWith("r102.unity"))
                throw new System.Exception("Clean r102 required");
            var all = sc.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            string t = "Missing=" + all.Sum(x => GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(x.gameObject)) + "\n";
            foreach (var a in s.GetComponentsInChildren<InvestigationActor>())
            {
                var render = a.GetComponentInChildren<SkinnedMeshRenderer>();
                t += a.name + " bounds=" + render.bounds + " head=" + (a.head ? a.head.position.ToString() : "clip-only pose owner") + "\n";
            }

            File.WriteAllText("Test/KetQua/investigation_r102/preplay.txt", t);
            EditorApplication.isPlaying = true;
            r.Log(t + "Entering Play; no old save load.");
        }
    }
}

